// CSD_RATIONALE_BEGIN
// Analysis of the failure pattern in attempt 58 reveals the root cause of
// the syntax collapse (76.7% vs 99% in attempt 43):
//
// Attempt 58 changed the guidance to omit "<<" and ">>" from the guidance text.
// Without seeing "<<query>>" in the guidance, Qwen3.5-4B generated SQL tokens
// (SELECT, column names) freely during the 5-step Phase 1 preamble instead of
// the "SQL: <<" prefix. Phase 2 then forced "<<" AFTER those free SQL tokens,
// producing malformed output like "SELECT city <<more_sql>>". The evaluator's
// span extractor found ">>" but no matching "<<" — hence 230/300 "unmatched
// visible close" and all wrong answers using text_fallback.
//
// The fix is simple: restore attempt 43's guidance (which includes "<<query>>"
// so the model emits "SQL: <<" naturally in Phase 1) and add targeted SQL
// pattern hints to address the 141 semantic mismatches (missing GROUP BY/HAVING,
// missing ORDER BY, selecting all columns instead of asked columns).
//
// Strategy (identical structure to attempt 43, proven at 52%/99%):
// Phase 1: 5-step unconstrained preamble; detect "<<" with RenderedEndsWith.
// Phase 2: Force OpenConstrainedSpan if "<<" not yet naturally emitted.
// Phase 3: GroupBoostedConstrainedStep(6.0) with IsCompletePrefix early-close.
// Phase 4: CloseSpanWithinBudget fallback (up to 80 steps) if span still open.
//
// Only the guidance text is changed vs attempt 43: we add three SQL pattern
// reminders (GROUP BY+HAVING for counting, ORDER BY for ranking, SELECT only
// the asked columns) that directly target the top semantic failure modes seen
// in the failing rollout examples.
// CSD_RATIONALE_END

// CSD_PROOF_SKETCH_BEGIN
// Invariant 1 (parser_validity):
//   insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
//
// Phase 1 preamble: Loop guard includes !insideConstrainedOut, so the body
//   runs only while insideConstrainedOut is false (implication vacuously true).
//   The only place we set insideConstrainedOut := true is when RenderedEndsWith
//   fires; we simultaneously set currentConstrainedOut := [], and
//   parser.IsValidPrefix([]) holds by the method precondition. On EOS break,
//   insideConstrainedOut stays false.
//
// Phase 2 OpenConstrainedSpan: Only reached when !insideConstrainedOut.
//   Helper postcondition sets currentConstrainedOut := [] and
//   insideConstrainedOut := true; IsValidPrefix([]) holds by precondition.
//
// Phase 3 main loop:
//   IsCompletePrefix branch: CloseConstrainedSpan sets insideConstrainedOut
//   := false (implication vacuously true) and clears currentConstrainedOut.
//   Normal GroupBoostedConstrainedStep branch: helper hard-masks to parser-
//   valid tokens plus EOS, so next is either EOS or parser-valid.
//   AppendConstrainedToken extends currentConstrainedOut by one parser-valid
//   token, preserving IsValidPrefix by the parser extension contract.
//   EOS branch: if IsCompletePrefix, CloseConstrainedSpan makes implication
//   vacuous; otherwise break without appending (invariant was already true).
//
// Phase 4 CloseSpanWithinBudget: postcondition guarantees
//   insideOut ==> parser.IsValidPrefix(currentOut).
//
// Invariant 2 (progress): |generated| <= |generatedPrefix| + steps
//
// Phase 1: Each UnconstrainedStep increments steps by 1 and appends at most
//   1 visible token (0 on EOS, 1 on non-EOS). Preserved each iteration.
// Phase 2: OpenConstrainedSpan increments steps by 1 and appends exactly one
//   "<<" token. |generated| grows by 1, steps grows by 1; preserved.
// Phase 3:
//   IsCompletePrefix branch: steps += 1; CloseConstrainedSpan appends at most
//   one ">>" token; net <= 1 token per +1 step.
//   Normal branch: steps += 1 (GroupBoostedConstrainedStep consumes 1 step),
//   AppendConstrainedToken appends 1 token; net exactly 1:1.
//   EOS + close path: steps += 1 (EOS step) then steps += 1 (close step);
//   generated grows by at most 1 (the ">>" from close); preserved.
// Phase 4: CloseSpanWithinBudget postcondition guarantees
//   |generatedOut| <= |generated_before_phase4| + closeBudget, and we set
//   steps += closeBudget; by transitivity |generated| <= |generatedPrefix| + steps.
// CSD_PROOF_SKETCH_END

generated := generatedPrefix;
insideConstrainedOut := insideConstrained;
currentConstrainedOut := currentConstrained;
cost := 0;

helpers.AppendTaskGuidance(lm, "Output SQL: <<query>> where query is a valid SQL SELECT statement using ONLY the exact table and column names from the provided schema. The SQL must be placed between << and >>. No explanation, no aliases not in the schema. Key SQL patterns: (1) For 'more than N occurrences of a group': GROUP BY col HAVING COUNT(*) > N. (2) For 'highest/lowest/most/least': ORDER BY col DESC or ASC, or use MAX/MIN. (3) SELECT only the specific column(s) the question explicitly asks about, not all columns from the table.");

var steps: nat := 0;

// Phase 1: Short preamble (at most 5 steps) to let model emit "SQL: <<" prefix
while steps < maxSteps && steps < 5 && !insideConstrainedOut
  invariant 0 <= steps <= maxSteps
  invariant lm.ValidTokensIdsLogits()
  invariant !insideConstrainedOut ==> currentConstrainedOut == []
  invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
  invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
  invariant |generated| <= |generatedPrefix| + steps
  decreases maxSteps - steps
{
  var next := helpers.UnconstrainedStep(lm, prompt, generated);
  steps := steps + 1;
  if next == eosToken {
    break;
  } else {
    generated := generated + [next];
    if RenderedEndsWith(generated, "<<") {
      insideConstrainedOut := true;
      currentConstrainedOut := [];
    }
  }
}

// Phase 2: Force open constrained span if not already inside one
if !insideConstrainedOut && steps < maxSteps {
  var og, oi, oc := helpers.OpenConstrainedSpan(lm, generated);
  generated := og;
  insideConstrainedOut := oi;
  currentConstrainedOut := oc;
  steps := steps + 1;
}

// Phase 3: Generate SQL under hard parser control with schema-token group boosting.
// IsCompletePrefix early-close is preserved — critical for 99% syntax rate.
while steps < maxSteps && insideConstrainedOut
  invariant 0 <= steps <= maxSteps
  invariant lm.ValidTokensIdsLogits()
  invariant !insideConstrainedOut ==> currentConstrainedOut == []
  invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
  invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
  invariant |generated| <= |generatedPrefix| + steps
  decreases maxSteps - steps
{
  if parser.IsCompletePrefix(currentConstrainedOut) {
    var cg, ci, cc := helpers.CloseConstrainedSpan(lm, parser, generated, currentConstrainedOut);
    generated := cg;
    insideConstrainedOut := ci;
    currentConstrainedOut := cc;
    steps := steps + 1;
    break;
  } else {
    var constrainedPrompt := prompt + generated[..|generated| - |currentConstrainedOut|];
    var next := helpers.GroupBoostedConstrainedStep(
      lm, parser, constrainedPrompt, currentConstrainedOut, validTokenGroups, 6.0, eosToken
    );
    steps := steps + 1;
    if next == eosToken {
      if parser.IsCompletePrefix(currentConstrainedOut) && steps < maxSteps {
        var cg, ci, cc := helpers.CloseConstrainedSpan(lm, parser, generated, currentConstrainedOut);
        generated := cg;
        insideConstrainedOut := ci;
        currentConstrainedOut := cc;
        steps := steps + 1;
      }
      break;
    } else {
      var ag, ai, ac := helpers.AppendConstrainedToken(
        lm, parser, generated, currentConstrainedOut, next
      );
      generated := ag;
      insideConstrainedOut := ai;
      currentConstrainedOut := ac;
    }
  }
}

// Phase 4: If span still open and budget remains, use CloseSpanWithinBudget
// to find the longest completable parse point and emit ">>".
if insideConstrainedOut && steps < maxSteps {
  var remaining := maxSteps - steps;
  var closeBudget: nat;
  if remaining <= 80 {
    closeBudget := remaining;
  } else {
    closeBudget := 80;
  }
  var cg, ci, cc := helpers.CloseSpanWithinBudget(
    lm, parser, prompt, generated, currentConstrainedOut, eosToken, closeBudget
  );
  generated := cg;
  insideConstrainedOut := ci;
  currentConstrainedOut := cc;
  steps := steps + closeBudget;
}

cost := steps;

